import json
import re
import secrets
from urllib.parse import urlencode

from django.conf import settings
from django.contrib.auth import login
from django.core.cache import cache
from django.http import HttpResponse, HttpResponseRedirect, JsonResponse
from django.shortcuts import render
from django.template.loader import render_to_string
from django.urls import reverse
from django.utils import timezone
from django.views.decorators.csrf import csrf_exempt
from django.views.decorators.http import require_GET, require_http_methods, require_POST
from lib.file_storage import save_file_obj
from PIL import Image, UnidentifiedImageError

from app.models import User
from jusprin.ledger import billing
from jusprin.ledger.account import account as account_summary
from jusprin.ledger.ledger import ensure_lots, has_paid
from jusprin.ledger.models import PrintReport
from jusprin.ledger.reports import ReportRefused, is_reported, submit_report
from jusprin.models import JusPrinPlan

from .aliases import get_aliases
from .auth import authenticate
from .errors import error_body


@require_GET
def models(request):
    """The aliases this person can pick, in display order. "format" is the
    backend the person is currently assigned for the alias, and so the
    endpoint the client should use for a new chat."""
    user = authenticate(request)
    if user is None:
        return HttpResponse(error_body('unauthorized'), status=401, content_type='application/json')
    ensure_lots(user.id)
    data = [{
        'id': alias.id,
        'label': alias.label,
        'format': alias.group_for(user.id).format,
        'efforts': list(alias.efforts),
        # Left out when there is none: released apps read it as a string.
        **({'default_effort': alias.default_effort} if alias.default_effort else {}),
        'tier': alias.tier,
        'credits': alias.credits,
        'images': alias.backends[alias.group_for(user.id).format].images,
    } for alias in get_aliases().values()]
    response = JsonResponse({'data': data})
    response['Cache-Control'] = 'no-store'
    return response


@csrf_exempt
@require_http_methods(['GET', 'DELETE'])
def account(request):
    """GET: the person's credits, plan and usage, for the composer's balance
    ring and the pre-send check. DELETE: deletes the account, from Delete
    account in the app's Preferences; the app signs out after."""
    user = authenticate(request)
    if user is None:
        return HttpResponse(error_body('unauthorized'), status=401, content_type='application/json')
    if request.method == 'DELETE':
        _delete_account(user)
        return HttpResponse(status=204)
    response = JsonResponse(account_summary(user))
    response['Cache-Control'] = 'no-store'
    return response


def _delete_account(user):
    """Ends the plan the account pays for now rather than at the end of its
    term, then deletes the account, and with it its credits, tokens and kept
    chats (jusprin.apps). A JusPrin 2 account is a user of its own, apart from
    the same person's Obico account (lib/syndicate.py), which stays. If
    Chargebee can't be reached, nothing is deleted."""
    plan = JusPrinPlan.objects.filter(user=user).first()
    if plan and plan.external_id:
        billing.end_plan_now(plan)
    user.delete()


@csrf_exempt
@require_POST
def cb_webhook(request):
    """Chargebee's webhook for JusPrin 2's own site. The post is trusted only
    for the event's id: the event is read back from that site, so a forged
    post changes nothing."""
    try:
        event_id = json.loads(request.body).get('id')
    except (ValueError, AttributeError):
        event_id = None
    cb_event = billing.retrieve_event(event_id) if isinstance(event_id, str) and event_id else None
    if cb_event is None:
        return HttpResponse(status=400)
    billing.handle_event(cb_event)
    return HttpResponse('')


@require_GET
def account_box(request):
    """The box near the top of the app's Account page: a piece of HTML, or
    nothing (204), which shows no box. The app asks with the person's token when
    they are signed in and with none when they are not. It shows the HTML in a
    frame that runs no scripts, so the box is words and pictures only and
    brings its own styles. Old apps rely only on "HTML or nothing"; what the box
    says can change freely."""
    signed_in = 'HTTP_AUTHORIZATION' in request.META
    user = authenticate(request) if signed_in else None
    # A token that no longer works also gets nothing: the app still shows that
    # person as signed in, so "Sign up today" would be wrong.
    if timezone.now() >= settings.JUSPRIN_V2_LAUNCH_OFFER_ENDS or (signed_in and (user is None or has_paid(user.id))):
        response = HttpResponse(status=204)
    else:
        response = HttpResponse(render_to_string('jusprin/v2/account_box.html', {'sign_up': not signed_in}))
    response['Cache-Control'] = 'no-store'
    return response


# Where the desktop app's loopback server sends the browser after it finishes,
# or fails, the OAuth code exchange.
@require_GET
def signed_in(request):
    return render(request, 'jusprin/v2/sign_in_result.html', {
        'heading': "You're signed in to JusPrin",
        'line': 'You can close this tab and go back to JusPrin.',
    })


@require_GET
def sign_in_failed(request):
    return render(request, 'jusprin/v2/sign_in_result.html', {
        'heading': "Signing in didn't finish",
        'line': 'Go back to JusPrin and try again.',
    })


WEB_LINK_KEY = 'jusprin_v2_web_link:{}'
WEB_LINK_FROM = re.compile(r'[a-z0-9_-]{1,32}')


@csrf_exempt
@require_POST
def web_link(request):
    """A link that opens one of the server's pages (JUSPRIN_V2_WEB_PAGES) signed
    in as the account whose token asks. JSON body: "page", the page's name, and
    "from", where in the app the click was, passed on to the page as ?from=. A
    page name the server doesn't know opens prices, so a newer app still gets a
    page from an older server. The link works once, for
    JUSPRIN_V2_WEB_LINK_SECONDS.

    A signed-out app sends no Authorization header and gets Credits and plans
    as a guest, whatever page it asked for; a token that is sent but wrong is
    still refused."""
    signed_out = 'HTTP_AUTHORIZATION' not in request.META
    user = None if signed_out else authenticate(request)
    if user is None and not signed_out:
        return _refuse('unauthorized', 401)
    try:
        body = json.loads(request.body or b'{}')
    except json.JSONDecodeError:
        return _refuse('invalid_request', 400)
    if not isinstance(body, dict):
        return _refuse('invalid_request', 400)
    page = body.get('page') if body.get('page') in settings.JUSPRIN_V2_WEB_PAGES else 'prices'
    origin = body.get('from')
    origin = origin if isinstance(origin, str) and WEB_LINK_FROM.fullmatch(origin) else None
    if signed_out:
        query = urlencode({'guest': 1, **({'from': origin} if origin else {})})
        response = JsonResponse({'url': request.build_absolute_uri(f"{settings.JUSPRIN_V2_WEB_PAGES['prices']}?{query}")})
        response['Cache-Control'] = 'no-store'
        return response
    token = secrets.token_urlsafe(32)
    cache.set(WEB_LINK_KEY.format(token), {'user_id': user.id, 'page': page, 'from': origin},
              settings.JUSPRIN_V2_WEB_LINK_SECONDS)
    response = JsonResponse({'url': request.build_absolute_uri(reverse('jusprin_v2_web_open', args=[token]))})
    response['Cache-Control'] = 'no-store'
    return response


@require_GET
def web_open(request, token):
    """Where a link from web_link lands: signs the browser in as that account,
    replacing whoever it was signed in as, and goes on to the page."""
    key = WEB_LINK_KEY.format(token)
    link = cache.get(key)
    # Only the request whose delete removes the entry signs in, so a link
    # opened twice at once still works once.
    user = User.objects.filter(id=link['user_id'], is_active=True).first() if link and cache.delete(key) else None
    if user is None:
        return render(request, 'jusprin/v2/sign_in_result.html', {
            'heading': 'This link has expired',
            'line': 'Go back to JusPrin and open the page again.',
        }, status=410)
    login(request, user, backend='app.accounts.SyndicateSpecificBackend')
    path = settings.JUSPRIN_V2_WEB_PAGES[link['page']]
    return HttpResponseRedirect(f"{path}?{urlencode({'from': link['from']})}" if link['from'] else path)


# Where the server's pages end: a checkout, a plan change, a cancel. The app
# watches its sheet for this address, closes the sheet and reads the account
# again; in a browser, the person reads this.
@require_GET
def web_done(request):
    return render(request, 'jusprin/v2/sign_in_result.html', {
        'heading': "You're all set",
        'line': 'You can close this tab and go back to JusPrin.',
    })


def _refuse(code: str, status: int) -> HttpResponse:
    return HttpResponse(error_body(code), status=status, content_type='application/json')


def _decodable(photo) -> bool:
    try:
        with Image.open(photo) as image:
            image.verify()
        return True
    except (UnidentifiedImageError, OSError, SyntaxError, Image.DecompressionBombError):
        return False
    finally:
        photo.seek(0)


def _store_photos(user, gcode_hash: str, photos) -> list:
    stamp = str(timezone.now().timestamp())
    urls = []
    for index, photo in enumerate(photos):
        path = f'print_reports/{user.id}/{gcode_hash}/{stamp}_{index}'
        _, url = save_file_obj(path, photo, settings.TIMELAPSE_CONTAINER, user.syndicate.name, long_term_storage=True)
        urls.append(url)
    return urls


@csrf_exempt
@require_POST
def print_reports(request):
    """A person's report on how a print came out. Multipart: gcode_hash, outcome,
    text, facts (a JSON object) and one or more photos."""
    user = authenticate(request)
    if user is None:
        return _refuse('unauthorized', 401)
    gcode_hash = request.POST.get('gcode_hash', '').strip()
    outcome = request.POST.get('outcome', '')
    text = request.POST.get('text', '').strip()
    try:
        facts = json.loads(request.POST.get('facts', '{}'))
    except json.JSONDecodeError:
        return _refuse('invalid_request', 400)
    if not gcode_hash or outcome not in dict(PrintReport.OUTCOMES) or not isinstance(facts, dict):
        return _refuse('invalid_request', 400)
    if len(text) < settings.JUSPRIN_V2_REPORT_MIN_TEXT:
        return _refuse('text_too_short', 400)
    photos = request.FILES.getlist('photos')
    if not photos:
        return _refuse('photo_needed', 400)
    if len(photos) > settings.JUSPRIN_V2_REPORT_MAX_PHOTOS or any(photo.size > settings.JUSPRIN_V2_REPORT_MAX_PHOTO_BYTES for photo in photos):
        return _refuse('request_too_large', 413)
    if not all(_decodable(photo) for photo in photos):
        return _refuse('photo_unreadable', 400)
    # Checked before the photos are stored; the unique constraint settles a race.
    if is_reported(user, gcode_hash):
        return _refuse('already_reported', 409)
    try:
        report = submit_report(user, gcode_hash, outcome, text, facts, _store_photos(user, gcode_hash, photos))
    except ReportRefused as refused:
        return _refuse(refused.code, 409)
    return JsonResponse({'id': report.id, 'credits': settings.JUSPRIN_V2_REPORT_CREDITS,
                         'created_at': report.created_at.isoformat()}, status=201)

