37	std::string scrub_error_text(std::string_view text)
38	{
39	    static const std::pair<std::regex, const char*> kScrub[] = {
40	        {std::regex(R"(\b(sk|pk|rk)-[A-Za-z0-9_-]{8,})"), "[key]"},
41	        {std::regex(R"((Bearer|bearer|x-api-key:?)\s+\S+)"), "$1 [key]"},
42	        {std::regex(R"([\w.+-]+@[\w-]+\.[\w.-]+)"), "[email]"},
43	        {std::regex(R"([A-Za-z0-9+/=_-]{48,})"), "[data]"},
44	    };
45	    std::string scrubbed(text.substr(0, 4 * kReportTextLimit));
46	    for (const auto& [pattern, replacement] : kScrub)
47	        scrubbed = std::regex_replace(scrubbed, pattern, replacement);
48	    if (scrubbed.size() > kReportTextLimit) {
49	        scrubbed.resize(kReportTextLimit);
50	        scrubbed += "...";
51	    }
52	    return scrubbed;
53	}
54	
55	void report_unexpected(UnexpectedError error)
56	{
57	    error.error_text = scrub_error_text(error.error_text);
58	    ReportSink current;
59	    {
60	        std::lock_guard<std::mutex> lock(sink_mutex());
61	        current = sink();
62	    }
63	    if (current)
64	        current(error);
65	    else
66	        log_report(error);
67	}
68	
69	ReportSink set_report_sink(ReportSink replacement)
70	{
71	    std::lock_guard<std::mutex> lock(sink_mutex());
72	    return std::exchange(sink(), std::move(replacement));
73	}
