// Checks the error-handling rules in AGENTS.md (Error handling) on JusPrin's
// own code: the C++ under src/slic3r/GUI/JusPrin and the pages' TypeScript.
// Every catch block rethrows, reports, or carries a written reason, and every
// entry of the expected-errors table has a test. Changing this file or the
// table (Support/ExpectedErrors.cpp) needs Kenneth's yes.
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';
import { describe, expect, it } from 'vitest';

const root = join(__dirname, '../../../../../..');
const jusprin = join(root, 'src/slic3r/GUI/JusPrin');

function files(dir: string, pattern: RegExp): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    if (statSync(path).isDirectory())
      return ['node_modules', 'dist', 'fonts', 'visual'].includes(name) ? [] : files(path, pattern);
    return pattern.test(name) && !/\.test\.tsx?$/.test(name) ? [path] : [];
  });
}

// Blanks out string and character literals and comments, keeping every
// newline and offset, so braces inside them don't count.
function code(text: string): string {
  return text.replace(/\/\/[^\n]*|\/\*[\s\S]*?\*\/|"(?:[^"\\\n]|\\.)*"|'(?:[^'\\\n]|\\.)*'|`(?:[^`\\]|\\.)*`/g,
    (match) => match.replace(/[^\n]/g, ' '));
}

// The text from the brace at open to its matching close brace, in source.
function block(source: string, blanked: string, open: number): string {
  let depth = 0;
  for (let i = open; i < blanked.length; ++i) {
    if (blanked[i] === '{') ++depth;
    else if (blanked[i] === '}' && --depth === 0) return source.slice(open, i + 1);
  }
  return source.slice(open);
}

// What a catch block may do instead of swallowing: rethrow (or throw a
// translated error), call the one reporting function (report_unexpected in
// C++, reportError in a page), or say why in a "Caught:" comment, inside the
// block or on the lines just above it.
const HANDLED = /\bthrow\b|\breport_unexpected\s*\(|\breportError\s*\(|\/\/\s*Caught:\s*\S/;

export function unexplainedCatches(path: string, source: string): string[] {
  const blanked = code(source);
  const found: string[] = [];
  // C++ and TypeScript catch clauses, and a promise's .catch(callback).
  const starts = /\bcatch\s*(\([^)]*\))?\s*\{|\.catch\(\s*(?:\([^)]*\)|\w+)\s*=>\s*\{/g;
  for (let match = starts.exec(blanked); match; match = starts.exec(blanked)) {
    const open = match.index + match[0].length - 1;
    const lineStart = source.lastIndexOf('\n', match.index) + 1;
    const line = source.slice(0, match.index).split('\n').length;
    // The comment lines just above the catch, if any.
    const before = source.slice(0, lineStart).split('\n');
    before.pop();
    const above: string[] = [];
    while (before.length && /^\s*\/\//.test(before[before.length - 1])) above.unshift(before.pop()!);
    if (!HANDLED.test(above.join('\n') + '\n' + block(source, blanked, open)))
      found.push(`${relative(root, path)}:${line}`);
  }
  return found;
}

describe('error handling', () => {
  it('finds a swallowed error and accepts a rethrow, a report or a written reason', () => {
    expect(unexplainedCatches(join(root, 'x.cpp'), 'try { f(); } catch (const std::exception&) {\n  return;\n}\n'))
      .toEqual(['x.cpp:1']);
    expect(unexplainedCatches(join(root, 'x.ts'), 'p.catch(() => {\n  // nothing\n});\n')).toEqual(['x.ts:1']);
    for (const handled of [
      'try { f(); } catch (...) { throw; }',
      'try { f(); } catch (const std::exception& e) { report_unexpected({"f", 0, {}, e.what()}); }',
      'try { f(); } catch {\n  // Caught: storage is off in a private window; the page works without it.\n}',
      'p.catch((error) => { client.reportError("reading a file", error); });',
    ])
      expect(unexplainedCatches(join(root, 'x.ts'), handled)).toEqual([]);
  });

  it('every catch in JusPrin\'s own code rethrows, reports, or says why', () => {
    const sources = [
      ...files(jusprin, /\.(cpp|hpp)$/),
      ...files(join(jusprin, 'AgentUI/src'), /\.tsx?$/),
      ...files(join(jusprin, 'HomeUI/src'), /\.tsx?$/),
      ...files(join(jusprin, 'WebShared'), /\.tsx?$/),
    ];
    const found = sources.flatMap((path) => unexplainedCatches(path, readFileSync(path, 'utf8')));
    // AGENTS.md, Error handling: a catch rethrows, calls report_unexpected
    // (reportError in a page), or carries a "// Caught: <reason>" comment.
    expect(found).toEqual([]);
  });

  it('every expected error in the table has a test', () => {
    const table = readFileSync(join(jusprin, 'Support/ExpectedErrors.cpp'), 'utf8');
    const codes = [...table.matchAll(/^\s*\{"([a-z_]+)",/gm)].map((m) => m[1]);
    expect(codes.length).toBeGreaterThan(0);
    const testDir = join(root, 'tests/agent');
    const tests = readdirSync(testDir).filter((name) => name.endsWith('.cpp'))
      .map((name) => readFileSync(join(testDir, name), 'utf8')).join('\n');
    expect(codes.filter((code) => !tests.includes(`"${code}"`))).toEqual([]);
  });
});

#include "ExpectedErrors.hpp"

#include <boost/log/trivial.hpp>

#include <algorithm>
#include <mutex>

namespace Slic3r::GUI::JusPrin {

namespace {

std::mutex                       g_mutex;
std::map<std::string, unsigned>  g_counts;

} // namespace

const std::vector<ExpectedError>& expected_errors()
{
    // The failures of a request to the AI (ProviderAgent::http_error). Each
    // has a test in tests/agent/test_provider_agent.cpp.
    static const std::vector<ExpectedError> kTable = {
        {"update_required", "The app is older than the oldest release JusPrin Cloud still serves.",
         "This version of JusPrin can no longer connect to JusPrin accounts.", "Get the new version, from the button."},
        {"invalid_credentials",
         "The person's JusPrin sign-in ended, or the AI provider rejected the person's own API key.",
         "Their sign-in has ended, or the API key was rejected.", "Sign in again, or update the key."},
        {"credits_exhausted", "The person is out of credits.", "They are out of credits.",
         "Get more credits, from the button."},
        {"request_too_large", "The chat, with its pictures and files, is larger than the AI service accepts.",
         "The request was too large for the AI service.",
         "Start a new chat, or send fewer pictures. The message does not say so today."},
        {"rate_limited", "The AI provider or JusPrin Cloud is limiting how fast this person may send.",
         "The AI service is rate limited.", "Wait a moment, then Retry."},
        {"service_overloaded", "The AI provider is overloaded.", "The AI service is overloaded.",
         "Wait a moment, then Retry."},
        {"service_unavailable", "The AI provider is down, or JusPrin Cloud cannot reach it.",
         "The AI service is temporarily unavailable.", "Retry, now or a little later."},
        {"timeout", "The AI provider took too long to answer, or the connection to it stalled.",
         "The AI request timed out.", "Retry."},
        {"network_error", "This computer could not reach the AI service: no network, or the connection failed.",
         "The AI request could not reach the service.", "Check the network, then Retry."},
    };
    return kTable;
}

const ExpectedError* expected_error(std::string_view code)
{
    const auto& table = expected_errors();
    const auto  found = std::find_if(table.begin(), table.end(), [code](const ExpectedError& e) { return e.code == code; });
    return found == table.end() ? nullptr : &*found;
}

void count_expected(std::string_view code)
{
    unsigned count = 0;
    {
        std::lock_guard<std::mutex> lock(g_mutex);
        count = ++g_counts[std::string(code)];
    }
    BOOST_LOG_TRIVIAL(info) << "JusPrin expected error: " << code << ", " << count << " this run";
}

std::map<std::string, unsigned> expected_error_counts()
{
    std::lock_guard<std::mutex> lock(g_mutex);
    return g_counts;
}

} // namespace Slic3r::GUI::JusPrin

#pragma once

// The one reporting function for JusPrin's own code (AGENTS.md, Error
// handling). Every branch nobody planned for calls report_unexpected: the
// last else, the default:, the catch-all, and a page's own unplanned failure,
// which reaches it over the bridge as a report_error message.
//
// Where a report goes: today, the app's log only. Sending reports to Sentry by
// default, with an opt-out, is agreed but not built; the sender goes behind
// this same call, so no caller changes when it lands.

#include <cstddef>
#include <functional>
#include <map>
#include <string>
#include <string_view>

namespace Slic3r::GUI::JusPrin {

struct UnexpectedError
{
    // What was being attempted, as a person would say it: "sending a message
    // to the AI", "finishing sign-in".
    std::string attempted;
    // The other side's HTTP status, or 0 when there was none.
    unsigned status{0};
    // The other side's request id, when it gave one.
    std::string request_id;
    // The other side's own error text. report_unexpected trims and scrubs it.
    std::string error_text;
    // Ids that tie the report to other records: chat, turn, provider, page.
    // Never content a person wrote.
    std::map<std::string, std::string> context;
};

void report_unexpected(UnexpectedError error);

// The error text as a report keeps it: at most kReportTextLimit bytes, with
// keys, email addresses and long opaque runs (base64 pictures) replaced.
inline constexpr std::size_t kReportTextLimit = 1000;
std::string scrub_error_text(std::string_view text);

// Tests: where reports go instead of the log. Returns the sink it replaced;
// an empty sink restores the log.
using ReportSink = std::function<void(const UnexpectedError&)>;
ReportSink set_report_sink(ReportSink sink);

} // namespace Slic3r::GUI::JusPrin

#include "ErrorReport.hpp"

#include <boost/log/trivial.hpp>

#include <mutex>
#include <regex>
#include <utility>

namespace Slic3r::GUI::JusPrin {

namespace {

std::mutex& sink_mutex()
{
    static std::mutex mutex;
    return mutex;
}

ReportSink& sink()
{
    static ReportSink current;
    return current;
}

void log_report(const UnexpectedError& error)
{
    std::string ids;
    for (const auto& [key, value] : error.context)
        ids += ", " + key + " " + value;
    BOOST_LOG_TRIVIAL(error) << "JusPrin unexpected: " << error.attempted << ", status " << error.status
                             << ", request id " << (error.request_id.empty() ? "none" : error.request_id) << ids
                             << ", error text " << error.error_text;
}

} // namespace

std::string scrub_error_text(std::string_view text)
{
    static const std::pair<std::regex, const char*> kScrub[] = {
        {std::regex(R"(\b(sk|pk|rk)-[A-Za-z0-9_-]{8,})"), "[key]"},
        {std::regex(R"((Bearer|bearer|x-api-key:?)\s+\S+)"), "$1 [key]"},
        {std::regex(R"([\w.+-]+@[\w-]+\.[\w.-]+)"), "[email]"},
        {std::regex(R"([A-Za-z0-9+/=_-]{48,})"), "[data]"},
    };
    std::string scrubbed(text.substr(0, 4 * kReportTextLimit));
    for (const auto& [pattern, replacement] : kScrub)
        scrubbed = std::regex_replace(scrubbed, pattern, replacement);
    if (scrubbed.size() > kReportTextLimit) {
        scrubbed.resize(kReportTextLimit);
        scrubbed += "...";
    }
    return scrubbed;
}

void report_unexpected(UnexpectedError error)
{
    error.error_text = scrub_error_text(error.error_text);
    ReportSink current;
    {
        std::lock_guard<std::mutex> lock(sink_mutex());
        current = sink();
    }
    if (current)
        current(error);
    else
        log_report(error);
}

ReportSink set_report_sink(ReportSink replacement)
{
    std::lock_guard<std::mutex> lock(sink_mutex());
    return std::exchange(sink(), std::move(replacement));
}

} // namespace Slic3r::GUI::JusPrin

