.jp-disclosure { display: flex; flex-direction: column; gap: var(--space-8); width: 340px; max-width: 100%; }

.jp-disclosure-header { display: flex; align-items: center; gap: var(--space-8); width: 100%; height: 28px; margin: 0; padding: 0; border: 0; border-radius: var(--radius-small); background: transparent; color: var(--text-secondary); text-align: left; cursor: pointer; }

.jp-disclosure-header:hover { color: var(--text-primary); }

.jp-disclosure-header:focus-visible { outline: 2px solid var(--border-focus); outline-offset: 0; }

