.jp-code { display: flex; flex-direction: column; gap: var(--space-8); width: 328px; max-width: 100%; }

.jp-code-label { color: var(--text-primary); }

.jp-code-cells { position: relative; display: flex; gap: var(--space-8); width: fit-content; border-radius: var(--radius-small); }

.jp-code-cell { display: flex; align-items: center; justify-content: center; flex: none; width: 48px; height: 48px; border-radius: var(--radius-small); background: var(--surface-canvas); color: var(--text-primary); box-shadow: inset 0 0 0 1px var(--border-subtle); }

.jp-code-cells:hover .jp-code-cell { box-shadow: inset 0 0 0 1px var(--border-strong); }

.jp-code-input { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; padding: 0; border: 0; opacity: 0; cursor: text; }

.jp-code-cells:focus-within { outline: 2px solid var(--border-focus); outline-offset: 0; }

.jp-code-support { color: var(--text-secondary); }

