.jp-code-disabled .jp-code-label, .jp-code-disabled .jp-code-support { color: var(--action-disabled-text); }

.jp-code-disabled .jp-code-cell, .jp-code-disabled .jp-code-cells:hover .jp-code-cell { background: var(--action-disabled); color: var(--action-disabled-text); box-shadow: inset 0 0 0 1px var(--border-subtle); }

.jp-code-disabled .jp-code-input { cursor: default; }

.jp-link { display: inline-flex; align-items: center; flex: none; height: 26px; margin: 0; padding: 0 var(--space-4); border: 0; border-radius: var(--radius-small); background: transparent; color: var(--action-primary); white-space: nowrap; cursor: pointer; }

.jp-link:hover:enabled { color: var(--action-primary-hover); }

.jp-link:active:enabled { color: var(--action-primary-pressed); }

.jp-link:disabled { color: var(--action-disabled-text); cursor: default; }

.jp-link:focus-visible { outline: 0; box-shadow: inset 0 0 0 2px var(--border-focus); }

.jp-link { align-self: flex-start; }

