import json,re
hits=[]
for line in open('8301dc30-2a1f-4651-a315-b94dc605b6fe.jsonl'):
    try: d=json.loads(line)
    except: continue
    if d.get('type')!='assistant': continue
    for c in d.get('message',{}).get('content',[]):
        if c.get('type')=='text':
            t=c['text']
            for m in re.finditer(r'[^.\n]*(no program|cannot be checked|can\'t be checked|judg(e)?ment|voluntar|mechanical|a program can|an agent has to|reviewer|cannot tell|can\'t tell)[^.\n]*\.', t, re.I):
                hits.append((d.get('timestamp','')[:16], m.group(0).strip()[:330]))
seen=set()
for ts,h in hits:
    if h in seen: continue
    seen.add(h); print(ts,'|',h)
EOF

