// AGENTS.md, Error handling: every status the AI service can answer with is
// either an expected error a person decided on, or reported. A status means
// the request reached a server, so it is never "could not reach".
TEST_CASE("every HTTP status from 400 to 599 is a named expected error or is reported", "[agent][loop][errors]")
{
    namespace JP = Slic3r::GUI::JusPrin;
    std::vector<JP::UnexpectedError> reports;
    const JP::ReportSink previous = JP::set_report_sink([&reports](const JP::UnexpectedError& e) { reports.push_back(e); });
    const std::string body = R"({"type":"error","error":{"type":"invalid_request_error","message":"messages.1: bad"},"request_id":"req_1"})";
    std::vector<std::string> failures;
    for (const bool account : {false, true}) {
        for (unsigned status = 400; status < 600; ++status) {
            ProviderAgentConfig config;
            config.profile                 = test_profile();
            config.profile.account_sign_in = account;
            Harness h(std::move(config));
            REQUIRE(h.agent->start(request_fixture()));
            reports.clear();
            h.fake->error(status, "HTTP error", body);
            const auto event = h.poll_until(AgentEventKind::Failed);
            REQUIRE(event);
            REQUIRE(event->error);
            const std::string where = (account ? "account " : "API key ") + std::to_string(status) + ": " + event->error->code;
            const bool reported = std::any_of(reports.begin(), reports.end(), [&](const JP::UnexpectedError& r) {
                return r.status == status && r.error_text.find("messages.1: bad") != std::string::npos;
            });
            if (event->error->code == "network_error")
                failures.push_back(where + " says the service could not be reached");
            else if (!JP::expected_error(event->error->code) && !reported)
                failures.push_back(where + " is neither expected nor reported");
            else if (reported && event->error->retryable)
                failures.push_back(where + " offers Retry for a failure nobody planned for");
        }
    }
    JP::set_report_sink(previous);
    CAPTURE(failures.size());
    CHECK(failures == std::vector<std::string>{});
}

