// Checks the error-handling rules in AGENTS.md (Error handling) on JusPrin's
// own code: the C++ under src/slic3r/GUI/JusPrin and the pages' TypeScript.
// Every catch block rethrows, reports, or carries a written reason, and every
// entry of the expected-errors table has a test. Changing this file or the
// table (Support/ExpectedErrors.cpp) needs Kenneth's yes.
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';
import { describe, expect, it } from 'vitest';

const root = join(__dirname, '../../../../../..');
const jusprin = join(root, 'src/slic3r/GUI/JusPrin');

function files(dir: string, pattern: RegExp): string[] {
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    if (statSync(path).isDirectory())
      return ['node_modules', 'dist', 'fonts', 'visual'].includes(name) ? [] : files(path, pattern);
    return pattern.test(name) && !/\.test\.tsx?$/.test(name) ? [path] : [];
  });
}

// Blanks out string and character literals and comments, keeping every
// newline and offset, so braces inside them don't count.
function code(text: string): string {
  return text.replace(/\/\/[^\n]*|\/\*[\s\S]*?\*\/|"(?:[^"\\\n]|\\.)*"|'(?:[^'\\\n]|\\.)*'|`(?:[^`\\]|\\.)*`/g,
    (match) => match.replace(/[^\n]/g, ' '));
}

// The text from the brace at open to its matching close brace, in source.
function block(source: string, blanked: string, open: number): string {
  let depth = 0;
  for (let i = open; i < blanked.length; ++i) {
    if (blanked[i] === '{') ++depth;
    else if (blanked[i] === '}' && --depth === 0) return source.slice(open, i + 1);
  }
  return source.slice(open);
}

// What a catch block may do instead of swallowing: rethrow (or throw a
// translated error), call the one reporting function (report_unexpected in
// C++, reportError in a page), or say why in a "Caught:" comment, inside the
// block or on the lines just above it.
const HANDLED = /\bthrow\b|\breport_unexpected\s*\(|\breportError\s*\(|\/\/\s*Caught:\s*\S/;

export function unexplainedCatches(path: string, source: string): string[] {
  const blanked = code(source);
  const found: string[] = [];
  // C++ and TypeScript catch clauses, and a promise's .catch(callback).
  const starts = /\bcatch\s*(\([^)]*\))?\s*\{|\.catch\(\s*(?:\([^)]*\)|\w+)\s*=>\s*\{/g;
  for (let match = starts.exec(blanked); match; match = starts.exec(blanked)) {
    const open = match.index + match[0].length - 1;
    const lineStart = source.lastIndexOf('\n', match.index) + 1;
    const line = source.slice(0, match.index).split('\n').length;
    // The comment lines just above the catch, if any.
    const before = source.slice(0, lineStart).split('\n');
    before.pop();
    const above: string[] = [];
    while (before.length && /^\s*\/\//.test(before[before.length - 1])) above.unshift(before.pop()!);
    if (!HANDLED.test(above.join('\n') + '\n' + block(source, blanked, open)))
      found.push(`${relative(root, path)}:${line}`);
  }
  return found;
}

describe('error handling', () => {
  it('finds a swallowed error and accepts a rethrow, a report or a written reason', () => {
    expect(unexplainedCatches(join(root, 'x.cpp'), 'try { f(); } catch (const std::exception&) {\n  return;\n}\n'))
      .toEqual(['x.cpp:1']);
    expect(unexplainedCatches(join(root, 'x.ts'), 'p.catch(() => {\n  // nothing\n});\n')).toEqual(['x.ts:1']);
    for (const handled of [
      'try { f(); } catch (...) { throw; }',
      'try { f(); } catch (const std::exception& e) { report_unexpected({"f", 0, {}, e.what()}); }',
      'try { f(); } catch {\n  // Caught: storage is off in a private window; the page works without it.\n}',
      'p.catch((error) => { client.reportError("reading a file", error); });',
    ])
      expect(unexplainedCatches(join(root, 'x.ts'), handled)).toEqual([]);
  });

  it('every catch in JusPrin\'s own code rethrows, reports, or says why', () => {
    const sources = [
      ...files(jusprin, /\.(cpp|hpp)$/),
      ...files(join(jusprin, 'AgentUI/src'), /\.tsx?$/),
      ...files(join(jusprin, 'HomeUI/src'), /\.tsx?$/),
      ...files(join(jusprin, 'WebShared'), /\.tsx?$/),
    ];
    const found = sources.flatMap((path) => unexplainedCatches(path, readFileSync(path, 'utf8')));
    // AGENTS.md, Error handling: a catch rethrows, calls report_unexpected
    // (reportError in a page), or carries a "// Caught: <reason>" comment.
    expect(found).toEqual([]);
  });

  it('every expected error in the table has a test', () => {
    const table = readFileSync(join(jusprin, 'Support/ExpectedErrors.cpp'), 'utf8');
    const codes = [...table.matchAll(/^\s*\{"([a-z_]+)",/gm)].map((m) => m[1]);
    expect(codes.length).toBeGreaterThan(0);
    const testDir = join(root, 'tests/agent');
    const tests = readdirSync(testDir).filter((name) => name.endsWith('.cpp'))
      .map((name) => readFileSync(join(testDir, name), 'utf8')).join('\n');
    expect(codes.filter((code) => !tests.includes(`"${code}"`))).toEqual([]);
  });
});

