            blocks.push_back(json{{"type", "tool_use"}, {"id", anthropic_tool_id(item.at("call_id").get<std::string>())},
                                  {"name", item.at("name")}, {"input", input.is_object() ? input : json::object()}});
        }
    }
    return blocks;
}

