import re, json, html
from pathlib import Path
from rows import rows, quotes
ALL = Path('../canvas-all/project')
meta = json.loads((ALL / 'canvas.json').read_text())
pages = {p['id']: p['name'] for p in meta['pages']}
def norm(t):
    t = html.unescape(t)
    for a, b in (('’', "'"), ('‘', "'"), ('“', '"'), ('”', '"'), ('…', '...'), (' ', ' '), ('&amp;', '&')):
        t = t.replace(a, b)
    return re.sub(r'\s+', ' ', t).lower()
boards = {}
for f in sorted(ALL.glob('*.dc.html')):
    raw = f.read_text()
    boards[f.name] = norm(re.sub(r'<[^>]+>', ' ', raw))
def grams(t, n=4):
    w = re.findall(r"[a-z0-9']+", t)
    return {' '.join(w[i:i+n]) for i in range(len(w) - n + 1)}
bgrams = {k: grams(v) for k, v in boards.items()}
def fragments(sentence):
    parts = re.split(r'\{[^}]*\}|%\d?\$?s|%\d%|\[[^\]]*\]', sentence)
    return [norm(p).strip(' .,:;·') for p in parts if len(p.strip()) >= 14]
def label(name):
    b = meta['boards'].get(name)
    if not b: return name.replace('.dc.html', '') + ' (a shared component)'
    return f"{name.replace('.dc.html', '')} [{pages.get(b.get('page'), b.get('page'))}] “{b.get('title', '')}”"
out = []
for i, r in enumerate(rows()):
    res = []
    for q in quotes(r['sentence']):
        fr = fragments(q)
        if not fr: res.append({'q': q, 'exact': [], 'near': [], 'skip': True}); continue
        exact = [k for k, v in boards.items() if all(f in v for f in fr)]
        near = []
        if not exact:
            g = set().union(*[grams(f) for f in fr]) if fr else set()
            if g:
                sc = sorted(((len(g & bgrams[k]) / len(g), k) for k in boards), reverse=True)[:2]
                near = [(round(s, 2), k) for s, k in sc if s >= 0.45]
        res.append({'q': q, 'exact': exact, 'near': near})
    out.append({'i': i, **r, 'matches': res})
Path('matches.json').write_text(json.dumps(out, ensure_ascii=False, indent=1))
for o in out:
    flags = []
    for m in o['matches']:
        if m.get('skip'): flags.append('·')
        elif m['exact']: flags.append('E%d' % len(m['exact']))
        elif m['near']: flags.append('n%.2f' % m['near'][0][0])
        else: flags.append('–')
    print(o['i'], '|', o['section'][:8], '|', o['cause'][:52], '|', ' '.join(flags))
EOF
